ence_must_be_fresh":true,"prior_done_not_evidence":true,"acceptance_state":"NOT_QUALIFIED","executable_binding_state":"AWAITING_EXACT_CONSUMER_ADAPTER_AND_RECEIPT","pass_rule":"EXACT_SUBJECT_CURRENT_VERIFIED_RECEIPT_AND_CHECKPOINT_SPECIFIC_ASSERTION","failure_rule":"MISSING_OR_STALE_OR_CROSS_SUBJECT_OR_FAKE_RECEIPT_MUST_BLOCK","negative_controls":["missing_receipt","stale_or_drifted","different_subject","synthetic_pass"],"owner":"CURRENTNESS_AUTHORITY@1.0.0","reused_validators":["PROGRAMMING_GITHUB_FILE_SHA256_ASSERT_V1","PROGRAMMING_GITHUB_FILE_TEXT_ASSERT_V1","PROGRAMMING_SUPABASE_CATALOG_ASSERT_V1"],"reusable_capabilities":["CURRENTNESS_AUTHORITY@1.0.0","SOURCE_RESOLUTION_POLICY@1.4.0"],"stage_structure_validator":null,"canonical_source":{"repository":"cristhianlujan/claude-persona-lf-patch","ref_rule":"EXACT_CURRENT_MAIN_REBOUND","path":"sandbox/lf_contract_gate_test/programming_agent_four_stage/wave1_boundary_contracts/analysis_v1_freeze_manifest_v1.json","git_sha256_rule":"FRESH_FILE_BYTES_NOT_GIT_BLOB_SHA"},"stage_specific_assertion":"Stage A15: exact current source and EKB/authority binding for Readback of all A1Q-A14Q required validated evidence and exact source revisions","acceptance_evidence_fields":["source_ref","resolved_main_sha","actual_sha256","current_capability_binding","readback_receipt_id","source_attestation_verified"],"boundary":"STATIC_SHAPE_OR_SHA_PASS_IS_NOT_ATTESTED_CURRENTNESS; existing validate_manifest is WAVE1_MANIFEST_NOT_A15_FREEZE_VALIDATOR","positive_control_spec":{"current_subject":true,"receipt_verified":true,"stage_specific_assertion":"Stage A15: exact current source and EKB/authority binding for Readback of all A1Q-A14Q required validated evidence and exact source revisions","expected":"PASS_ONLY_IF_ALL_INDEPENDENT_AND_CURRENT"},"negative_control_spec":{"mutation":"SUBJECT_OR_SOURCE_DRIFT_OR_MISSING_MATERIAL","expected":"FAIL_OR_BLOCK_NOT_PASS","no_case_family_hardcode":true}}},{"code":"A15Q_C2","order":2,"title":"Salida real gobernada","evidence_class":"REAL_EXECUTION_RECEIPT","required_proof":"Reconciliación Git-Supabase/juez/PG-01 con huellas actuales","forbidden":"FIXTURE_REPLAY_OR_SELF_DECLARED_MODEL_EXECUTION","validator_contract":{"schema":"ANALYSIS_QUALIFICATION_CHECKPOINT_VALIDATOR_BINDING_V1","checkpoint_code":"A15Q_C2","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A15Q/A15Q_C2","criterion":"Reconciliación Git-Supabase/juez/PG-01 con huellas actuales","evidence_must_be_fresh":true,"prior_done_not_evidence":true,"acceptance_state":"NOT_QUALIFIED","executable_binding_state":"AWAITING_EXACT_CONSUMER_ADAPTER_AND_RECEIPT","pass_rule":"EXACT_SUBJECT_CURRENT_VERIFIED_RECEIPT_AND_CHECKPOINT_SPECIFIC_ASSERTION","failure_rule":"MISSING_OR_STALE_OR_CROSS_SUBJECT_OR_FAKE_RECEIPT_MUST_BLOCK","negative_controls":["missing_receipt","stale_or_drifted","different_subject","synthetic_pass"],"owner":"EXISTING_PROFILE_RUNTIME","reused_validators":["profiles/programming_analysis_lf/validators/runtime_validate.py"],"reused_capabilities":["TYPED_EVIDENCE_REGISTRY@3.0.0","CURRENTNESS_AUTHORITY@1.0.0"],"stage_output_selector":"A15","stage_specific_assertion":"Readback of all A1Q-A14Q required validated evidence and exact source revisions","acceptance_evidence_fields":["governed_execution_id","router_dispatch_receipt_id","producer_execution_id","provider_response_id_attested_by_transport","exact_profile_version","input_digest_sha256","output_digest_sha256","stage_output_ref","stage_source_receipt_refs","evidence_ledger_verified_ref"],"boundary":"PROFILE_STRUCTURAL_PASS_AND_PROVIDER_ID_GENERATED_BY_MODEL_DO_NOT_COUNT","positive_control_spec":{"current_subject":true,"receipt_verified":true,"stage_specific_assertion":"Readback of all A1Q-A14Q required validated evidence and exact source revisions","expected":"PASS_ONLY_IF_ALL_INDEPENDENT_AND_CURRENT"},"negative_control_spec":{"mutation":"SUBJECT_OR_SOURCE_DRIFT_OR_MISSING_MATERIAL","expected":"FAIL_OR_BLOCK_NOT_PASS","no_case_family_hardcode":true}}},{"code":"A15Q_C3","order":3,"title":"Aseguramiento independiente","evidence_class":"INDEPENDENT_REVIEW_OR_CONSUMER_RECEIPT","required_proof":"Aprobación independiente de freeze; no inferirla de DONE documental","forbidden":"PRODUCER_SELF_JUDGMENT_OR_STRUCTURAL_PASS_AS_SEMANTIC_PASS","validator_contract":{"schema":"ANALYSIS_QUALIFICATION_CHECKPOINT_VALIDATOR_BINDING_V1","checkpoint_code":"A15Q_C3","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A15Q/A15Q_C3","criterion":"Aprobación independiente de freeze; no inferirla de DONE documental","evidence_must_be_fresh":true,"prior_done_not_evidence":true,"acceptance_state":"NOT_QUALIFIED","executable_binding_state":"AWAITING_EXACT_CONSUMER_ADAPTER_AND_RECEIPT","pass_rule":"EXACT_SUBJECT_CURRENT_VERIFIED_RECEIPT_AND_CHECKPOINT_SPECIFIC_ASSERTION","failure_rule":"MISSING_OR_STALE_OR_CROSS_SUBJECT_OR_FAKE_RECEIPT_MUST_BLOCK","negative_controls":["missing_receipt","stale_or_drifted","different_subject","synthetic_pass"],"owner":"INDEPENDENT_ASSURANCE@2.0.1","reused_capabilities":["INDEPENDENT_ASSURANCE@2.0.1","TYPED_EVIDENCE_REGISTRY@3.0.0"],"reused_entrypoint":"public.lf_independent_review_begin_v3","reused_validator_ref":"sandbox/lf_contract_gate_test/transversal_assets/independent_assurance/validate_independent_review_subject_envelope_v3.py","subject_type":"PROGRAMMING_ANALYSIS_STAGE_QUALIFICATION","stage_specific_assertion":"Independent frozen-release verdict on 14/14 and A9 receipt; no programmatic self-freeze","acceptance_evidence_fields":["frozen_subject_sha256","producer_execution_id","reviewer_execution_id","review_dispatch_receipt_id","review_verdict_ref","evidence_ledger_verified_ref","exact_stage_assertion_results","no_critical_regressions"],"independent_reviewer_required":true,"boundary":"HISTORICAL_OTHER_SUBJECT_PASS_IS_FORBIDDEN","terminal_dependencies":{"all_earlier_qualifiers_required":14,"legacy_done_not_sufficient":true},"positive_control_spec":{"current_subject":true,"receipt_verified":true,"stage_specific_assertion":"Independent frozen-release verdict on 14/14 and A9 receipt; no programmatic self-freeze","expected":"PASS_ONLY_IF_ALL_INDEPENDENT_AND_CURRENT"},"negative_control_spec":{"mutation":"SUBJECT_OR_SOURCE_DRIFT_OR_MISSING_MATERIAL","expected":"FAIL_OR_BLOCK_NOT_PASS","no_case_family_hardcode":true}}}]}]'::jsonb;
  v_record jsonb;
  v_checkpoint jsonb;
  v_parent record;
  v_child bigint;
  v_code text;
  v_expected integer := 0;
  v_created integer := 0;
  v_count integer := 0;
  v_meta jsonb;
  v_specs jsonb;
  v_inputs jsonb;
BEGIN
  -- Exact prestate, no blind backfill or parallel registry.
  IF jsonb_array_length(v_catalog) <> 15
     OR (SELECT count(*) FROM programacion.engineering_plan_units u
         JOIN programacion.engineering_work_items w ON w.id=u.work_item_id
         WHERE u.plan_code=v_plan AND u.unit_code ~ '^A([1-9]|1[0-5])$'
           AND u.disposition='ASSIGNED' AND w.status='DONE') <> 15
     OR EXISTS (SELECT 1 FROM programacion.engineering_plan_units u
       JOIN programacion.engineering_work_checkpoints c ON c.work_item_id=u.work_item_id
       WHERE u.plan_code=v_plan AND u.unit_code ~ '^A([1-9]|1[0-5])$')
     OR EXISTS (SELECT 1 FROM programacion.engineering_plan_units
       WHERE plan_code=v_plan AND unit_code ~ '^A([1-9]|1[0-5])Q$')
     OR EXISTS (SELECT 1 FROM programacion.engineering_work_items
       WHERE work_code ~ '^PA-AN-Q(0[1-9]|1[0-5])$')
  THEN RAISE EXCEPTION 'ANALYSIS_QUALIFICATION_PRESTATE_DRIFT'; END IF;

  FOR v_record IN SELECT item FROM jsonb_array_elements(v_catalog) AS x(item) LOOP
    v_code := v_record->>'unit_code';
    IF (v_record->>'qualification_unit_code') IS DISTINCT FROM v_code||'Q'
       OR jsonb_array_length(v_record->'checkpoints') <> 3
       OR (SELECT count(distinct c->>'code') FROM jsonb_array_elements(v_record->'checkpoints') c) <> 3
    THEN RAISE EXCEPTION 'ANALYSIS_QUALIFICATION_CATALOG_INVALID:%',v_code; END IF;

    SELECT u.id,u.work_item_id,u.lot_from,u.lot_to,u.plan_event_id,w.workstream_id,w.priority,
           w.status,w.work_code,w.source_ref,w.target_domain
    INTO STRICT v_parent
    FROM programacion.engineering_plan_units u
    JOIN programacion.engineering_work_items w ON w.id=u.work_item_id
    WHERE u.plan_code=v_plan AND u.unit_code=v_code
      AND u.disposition='ASSIGNED' AND w.status='DONE'
    FOR UPDATE OF u,w;

    v_specs := '{}'::jsonb;
    v_inputs := '{}'::jsonb;
    FOR v_checkpoint IN SELECT item FROM jsonb_array_elements(v_record->'checkpoints') AS x(item) LOOP
      IF (v_checkpoint->>'code') IS DISTINCT FROM v_code||'Q_C'||(v_checkpoint->>'order')
         OR (v_checkpoint->>'order')::int NOT BETWEEN 1 AND 3
         OR coalesce(v_checkpoint->>'required_proof','')=''
         OR v_checkpoint#>>'{validator_contract,schema}' IS DISTINCT FROM 'ANALYSIS_QUALIFICATION_CHECKPOINT_VALIDATOR_BINDING_V1'
         OR v_checkpoint#>>'{validator_contract,checkpoint_code}' IS DISTINCT FROM v_checkpoint->>'code'
         OR v_checkpoint#>>'{validator_contract,acceptance_state}' IS DISTINCT FROM 'NOT_QUALIFIED'
         OR coalesce(v_checkpoint#>>'{validator_contract,stage_specific_assertion}','')=''
         OR v_checkpoint#>>'{validator_contract,executable_binding_state}' IS DISTINCT FROM 'AWAITING_EXACT_CONSUMER_ADAPTER_AND_RECEIPT'
      THEN RAISE EXCEPTION 'ANALYSIS_QUALIFICATION_CHECKPOINT_CONTRACT_INVALID:%',v_code; END IF;
      v_specs := v_specs || jsonb_build_object(v_checkpoint->>'code',
        jsonb_build_object(
          'status','BLOCK_VERIFIED_OPERATIONAL_EVIDENCE_REQUIRED',
          'precision','EXPLICIT_ACTUAL_PROOF_ONLY',
          'action_kind','READBACK_ONCE',
          'recipe_mode','READBACK_EXACT',
          'requires_material_execution',false,
          'expected_evidence_class',v_checkpoint->>'evidence_class',
          'validator_contract',v_checkpoint->'validator_contract',
          'pass_when',v_checkpoint#>>'{validator_contract,pass_rule}',
          'failure_rule',v_checkpoint#>>'{validator_contract,failure_rule}',
          'forbidden',jsonb_build_array(v_checkpoint->>'forbidden','SYNTHETIC_PASS','LEGACY_DONE_AS_OPERATING_PROOF'),
          'target',jsonb_build_object('current_unit',v_code||'Q','legacy_parent',v_code),
          'next_action','BIND_CANONICAL_EXECUTOR_AND_CURRENT_RECEIPT_BEFORE_READY'));
      v_inputs := v_inputs || jsonb_build_object(v_checkpoint->>'code',
        jsonb_build_object(
          'inputs',jsonb_build_object('queries','[]'::jsonb,'db_objects','[]'::jsonb,
                    'assets','[]'::jsonb,'events','[]'::jsonb,'artifacts','[]'::jsonb),
          'expected_result',v_checkpoint->>'required_proof',
          'validator_contract',v_checkpoint->'validator_contract',
          'missing_typed',jsonb_build_array(jsonb_build_object(
               'blocking',true,
               'code','OPERATIONAL_ATTESTED_EVIDENCE_NOT_YET_CAPTURED',
               'required_evidence_class',v_checkpoint->>'evidence_class'))));
    END LOOP;

    v_meta := jsonb_build_object(
      'schema','PROGRAMMING_ANALYSIS_QUALIFICATION_CHILD_V1',
      'phase','OPERATIONAL_QUALIFICATION',
      'legacy_parent_unit_code',v_code,
      'legacy_parent_work_item_id',v_parent.work_item_id,
      'legacy_parent_status_at_creation','DONE',
      'legacy_parent_evidence_not_reused_as_qualification',true,
      'qualifier_state','EVIDENCE_PENDING',
      'scope','ANALYSIS_ONLY',
      'no_parallel_engine',true,
      'operational_ready',false,
      'runtime_activated',false,
      'checkpoint_contracts',v_record->'checkpoints',
      'action_specs_v1',v_specs,
      'source_pack_v2',jsonb_build_object('checkpoint_inputs',v_inputs),
      'source_catalog_ref','docs/programming-agent/ANALYSIS_QUALIFICATION_CHECKPOINT_CATALOG_V1.json');

    INSERT INTO programacion.engineering_work_items(
      work_code,workstream_id,parent_work_item_id,title,objective,expected_result,
      work_type,priority,status,assignee_type,assignee_ref,target_domain,source_ref,
      acceptance_criteria,created_by_execution_id)
    VALUES (
      'PA-AN-Q'||lpad(substring(v_code from 2),2,'0'),
      v_parent.workstream_id,v_parent.work_item_id,
      v_code||'Q — Cualificación operativa de '||v_code,
      v_record->>'objective',
      'Evidence-attested, independently judged Analysis readiness; historical DONE untouched.',
      'QA',v_parent.priority,'BACKLOG','AGENT','SUPER_ADMIN',
      v_parent.target_domain,
      'github://cristhianlujan/claude-persona-lf-patch/docs/programming-agent/ANALYSIS_QUALIFICATION_CHECKPOINT_CATALOG_V1.json',
      (SELECT jsonb_agg(c->>'required_proof' ORDER BY (c->>'order')::int)
       FROM jsonb_array_elements(v_record->'checkpoints') c),v_actor)
    RETURNING id INTO v_child;

    INSERT INTO programacion.engineering_plan_units(
      plan_code,unit_code,unit_class,lot_code,lot_from,lot_to,
      title,exit_criterion,plan_event_id,work_item_id,
      created_by_execution_id,unit_metadata)
    VALUES (
      v_plan,v_code||'Q','OPERATIONAL_QUALIFICATION','ANALYSIS-QUALIFICATION-V1',
      v_parent.lot_from,v_parent.lot_to,
      v_code||'Q — Cualificación operativa de '||v_code,
      '3 current, real, independently verifiable checkpoint receipts, no false READY',
      v_parent.plan_event_id,v_child,v_actor,v_meta);

    INSERT INTO programacion.engineering_work_dependencies(
      work_item_id,depends_on_work_item_id,relation_type,created_by_execution_id)
    VALUES (v_child,v_parent.work_item_id,'REQUIRES',v_actor);

    INSERT INTO programacion.engineering_work_checkpoints(
      work_item_id,checkpoint_code,title,sequence_no,weight,required,status,created_by_execution_id)
    SELECT v_child,c->>'code',c->>'title',(c->>'order')::int,1.0,true,'PENDING',v_actor
    FROM jsonb_array_elements(v_record->'checkpoints') c
    ORDER BY (c->>'order')::int;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count<>3 THEN RAISE EXCEPTION 'ANALYSIS_QUALIFICATION_CHECKPOINT_COUNT_DRIFT:%',v_code; END IF;
    v_expected := v_expected + 3;
    v_created := v_created + 1;

    INSERT INTO programacion.engineering_work_updates(
      work_item_id,update_type,summary,detail,next_action,evidence_refs,
      reported_by,created_by_execution_id)
    VALUES (v_child,'NEXT_STEP','Cualificación operativa separada de cierre documental',
      '3 checkpoints PENDING: fuente actual atestada; ejecución real; aseguramiento independiente.',
      'Bind per-checkpoint governed source/executor/judge evidence before transition',
      jsonb_build_array('PROGRAMMING-ANALYSIS-STAGE-SOURCE-ATTESTATION-GAP-001',
                        'PROGRAMMING-ANALYSIS-A14-EVIDENCE-TIER-FALSE-READY-001'),
      'ANALYSIS_QUALIFICATION_CATALOG',v_actor);
  END LOOP;

  IF v_created<>15 OR v_expected<>45
    OR (SELECT count(*) FROM programacion.engineering_plan_units
      WHERE plan_code=v_plan AND unit_code ~ '^A([1-9]|1[0-5])Q$')<>15
    OR (SELECT count(*) FROM programacion.engineering_work_checkpoints c
        JOIN programacion.engineering_plan_units u ON u.work_item_id=c.work_item_id
        WHERE u.plan_code=v_plan AND u.unit_code ~ '^A([1-9]|1[0-5])Q$'
          AND c.status='PENDING' AND c.required)=0
    OR (SELECT count(*) FROM programacion.engineering_work_checkpoints c
        JOIN programacion.engineering_plan_units u ON u.work_item_id=c.work_item_id
        WHERE u.plan_code=v_plan AND u.unit_code ~ '^A([1-9]|1[0-5])Q$'
          AND c.status='PENDING' AND c.required)<>45
    OR (SELECT count(*) FROM programacion.engineering_plan_units u
        JOIN programacion.engineering_work_items w ON w.id=u.work_item_id
        WHERE u.plan_code=v_plan AND u.unit_code ~ '^A([1-9]|1[0-5])$'
          AND w.status='DONE')<>15
  THEN RAISE EXCEPTION 'ANALYSIS_QUALIFICATION_POSTSTATE_DIVERGENCE'; END IF;
END;
$analysis_qualification$;
COMMIT;
